  ('f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'fast-national-university-of-computer-and-emerging-sciences', 'Islamabad'),
  ('f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'university-of-engineering-and-technology-peshawar', 'Peshawar'),
  ('9a147d3a-43d9-5330-a498-d74bfc593a36'::uuid, 'fast-national-university-of-computer-and-emerging-sciences', 'Lahore'),
  ('eab45168-c948-5568-a646-cdd3c4d2c6bb'::uuid, 'fast-national-university-of-computer-and-emerging-sciences', 'Peshawar'),
  ('78b67297-fb47-591d-ac3f-e1f52fbcfeaa'::uuid, 'fast-national-university-of-computer-and-emerging-sciences', 'Islamabad'),
  ('5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, 'fast-national-university-of-computer-and-emerging-sciences', 'Islamabad'),
  ('e95a66ce-9aa8-5651-af65-6e855a250048'::uuid, 'quaid-i-azam-university', 'Islamabad'),
  ('969ca84f-b57e-5027-a588-1c9385f61feb'::uuid, 'national-university-of-sciences-and-technology', 'Islamabad'),
