-- 5. Confessions and public posts ----------------------------------------
-- Bodies are deliberately mundane. Nothing here names a real person.
insert into public.posts (id, channel_id, author_id, body, is_anonymous, category, created_at)
select v.id, ch.id, v.author_id, v.body, v.is_anonymous, v.category::public.post_category, now() - (v.age_hours || ' hours')::interval
from (values
  ('b9ab15c3-97d3-5f15-a20d-5f33b3a482a5'::uuid, 'f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'To the person who returned my lost ID card to the front desk last week: I do not know who you are and I probably never will, but I hope both sides of your pillow are cold tonight. Small kindness, big week.', true, 'complaints', 2, 'fast-national-university-of-computer-and-emerging-sciences', 'Peshawar'),
  ('ff74ddb0-ce13-5ec9-afb8-0a00bd3d9831'::uuid, 'f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'Genuine question for seniors: is the fourth semester actually harder, or does everyone just say that to scare us? Trying to plan my society commitments and I would rather know now.', false, 'advice', 4, 'fast-national-university-of-computer-and-emerging-sciences', 'Peshawar'),
  ('2d0149ad-f0a1-5b8d-a8fc-d9777bece7be'::uuid, '9a147d3a-43d9-5330-a498-d74bfc593a36'::uuid, 'Our section has a two-person group project and one of us has done every single line of code. I am the other one. I have learned more from watching them work than from the entire course so far, and I am not sure whether to feel grateful or guilty.', true, 'general', 7, 'fast-national-university-of-computer-and-emerging-sciences', 'Peshawar'),
  ('75adb29c-f9f6-57ab-a29a-2b3a3da21e4a'::uuid, 'eab45168-c948-5568-a646-cdd3c4d2c6bb'::uuid, 'The hostel mess served the same daal for eleven days straight. Eleven. I am not asking for biryani. I am asking for variety. A rotation. Anything.', true, 'complaints', 11, 'fast-national-university-of-computer-and-emerging-sciences', 'Islamabad'),
  ('730f3ea5-e0f5-5991-ac96-7fc95d8e90cf'::uuid, 'eab45168-c948-5568-a646-cdd3c4d2c6bb'::uuid, 'Anyone else find that the 8am lecture has a completely different attendance crowd than the 11am? It is like two different universities sharing one building.', false, 'advice', 14, 'fast-national-university-of-computer-and-emerging-sciences', 'Islamabad'),
  ('663d99ee-6ed3-5dc2-a406-3e983435d8b8'::uuid, '78b67297-fb47-591d-ac3f-e1f52fbcfeaa'::uuid, 'I came into this university convinced I was going to change my field after the first semester. Two years later I am the person helping juniors survive the same course. It does get better, and it gets better faster than you expect.', true, 'general', 19, 'fast-national-university-of-computer-and-emerging-sciences', 'Lahore'),
  ('1d971267-94d6-5fab-a23c-09c838fa1808'::uuid, 'e95a66ce-9aa8-5651-af65-6e855a250048'::uuid, 'Reminder: scholarship and financial-aid applications for the next cycle close at the end of this month. The office has extended walk-in hours on weekdays. Bring your previous transcript and your income documents — they will not accept photocopies of photocopies.', false, 'career', 26, 'national-university-of-sciences-and-technology', 'Islamabad'),
  ('4fe53211-7905-59b6-a15c-c0805e8180e0'::uuid, '5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, 'There is a lecturer here who marks assignments at 2am and still replies to emails at 6am. I do not know how. I do not want to know how. I just want to say thank you, because I have never once waited more than a day for a reply.', true, 'academics', 31, 'national-university-of-sciences-and-technology', 'Islamabad'),
  ('d61e8b23-f68c-51c2-aa9c-ac83961b1cd6'::uuid, '5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, 'Has anyone taken the machine learning elective without the prerequisite? Timeline says I need the maths course first but I already did something very similar at A-levels. Wondering if the department will waive it.', false, 'advice', 38, 'national-university-of-sciences-and-technology', 'Islamabad'),
  ('4dee3ee1-2300-58cd-afe9-124243fc15d0'::uuid, 'ab8ee3ee-3b72-50da-a419-b15a62b3158b'::uuid, 'The power went out in the middle of our lab practical and half the class immediately started studying for the other subject by phone torch. Something about that moment felt enormously Pakistani and I mean that as a compliment.', true, 'campus_life', 45, 'university-of-engineering-and-technology-peshawar', 'Peshawar'),
  ('3aa81a54-59c1-5a47-a95b-db221e0e7661'::uuid, '0afbfff3-f104-5daa-afa9-111a9787dcba'::uuid, 'Our workshop has a broken lathe that three batches have now reported and nobody has fixed. Tagging the department in case a society member knows who to actually email.', false, 'complaints', 52, 'university-of-engineering-and-technology-peshawar', 'Peshawar'),
  ('a48b5e9b-cb90-53d0-ac2d-35cc9990c5c6'::uuid, '969ca84f-b57e-5027-a588-1c9385f61feb'::uuid, 'I have been at this university for three years and I only found out last week that the library basement has a quiet reading room. Three years. If you are new: it exists, it is empty, it is yours.', true, 'campus_life', 60, 'lahore-university-of-management-sciences', 'Lahore'),
  ('2325c9d7-58f9-53c7-a17c-0f7229987f2f'::uuid, '0e4df7cc-5ef6-50c1-a170-96545dc6d150'::uuid, 'Case competition season is starting and every team needs one person who can make a deck look decent. That person is always the same person. If you are that person, charge for it.', false, 'career', 68, 'lahore-university-of-management-sciences', 'Lahore'),
  ('d49fd58d-b5ad-5ef3-a2c2-9c85feb15c47'::uuid, '52c4e77d-a51d-5f55-a2d1-f08feee355e8'::uuid, 'The mess queue at 8pm is a social experiment and I am the control group. Whoever decided dinner should start at the same time as the evening class ending deserves a very long conversation.', true, 'complaints', 76, 'institute-of-business-administration', 'Karachi'),
  ('a2c394a4-c571-576c-a76f-a6b263eaaa68'::uuid, '26060574-2c8d-59b6-ac65-fc71ec27c97e'::uuid, 'Took the wrong bus home on Wednesday, ended up forty minutes in the wrong direction, and met a final-year student from my own department who gave me the most useful advice about internships I have heard all year. Best mistake.', false, 'general', 84, 'institute-of-business-administration', 'Karachi'),
  ('0d7eeb77-0b5c-57bd-a262-c9903ce2874f'::uuid, 'c616a515-1909-5334-ac6e-a9aae9284832'::uuid, 'I have started leaving my notes on the shared drive with my initials in the filename. No idea if anyone uses them. If you do, no need to say anything, just pass it on to the next batch.', true, 'advice', 93, 'quaid-i-azam-university', 'Islamabad'),
  ('ba79aff8-d23f-5b22-a02e-14fba9a639ce'::uuid, '519b8ad4-c52f-5fbd-a43e-db8b44f9593b'::uuid, 'Standing offer: if you are stuck on the data structures assignment and cannot afford a tutor, comment here and I will go through it with you in the library. No payment, no strings, I have been stuck before.', false, 'advice', 102, 'comsats-university-islamabad', 'Islamabad'),
  ('9286724e-f204-5ea6-a919-a1e0e4c0b94e'::uuid, '18b263cb-e11a-5e6c-a8b6-17b9cfc1af04'::uuid, 'The escalator in the engineering block has been out of service since the start of the semester and there is now a genuine traffic jam on the stairs between classes. This is a real accessibility problem, not just an inconvenience.', true, 'complaints', 118, 'ned-university-of-engineering-and-technology', 'Karachi'),
  ('4907056c-ba87-5b0c-ae2d-89378431668b'::uuid, 'b4c7206d-9318-585d-ab4e-8eac52e24805'::uuid, 'Something nobody tells you about engineering: you will spend more time writing documentation and arguing in meetings than doing the maths you actually came here for. Practice explaining your work plainly. It is the higher-leverage skill.', false, 'career', 130, 'ghulam-ishaq-khan-institute-of-engineering-sciences-and-technology', 'Swabi'),
  ('2c45cedc-3207-5fb9-a01e-e9ea44df9606'::uuid, '9851c869-e57e-5937-a1f8-8246907504f2'::uuid, 'Whoever runs the campus radio at lunchtime, your playlist on Tuesday was the only reason I stayed on campus instead of going home. Thank you.', true, 'memes', 145, 'university-of-engineering-and-technology-lahore', 'Lahore'),
  ('c4df3b02-9ced-51cd-a72f-da77eeed70ac'::uuid, '1ad7f11d-5e3c-5dd7-a9c7-7bb5f7964cec'::uuid, 'Quick poll for everyone who lives on campus — genuinely curious how the new timetable is landing now that we are a few weeks in.', false, 'advice', 160, 'bahria-university', 'Islamabad'),
  ('a03d4990-e875-5165-a7ce-1c6b03bbd606'::uuid, 'f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'Second attempt: does anyone have last year''s question bank for the discrete maths final? I will happily trade for my summarised notes from the whole course.', true, 'advice', 178, 'fast-national-university-of-computer-and-emerging-sciences', 'Peshawar'),
  ('245143b6-01f4-5475-acc9-11a90fd227eb'::uuid, 'eab45168-c948-5568-a646-cdd3c4d2c6bb'::uuid, 'A note to first years that I wish someone had given me: your first semester marks are not a verdict on your ability. They are a verdict on how well you had learned to study at that exact moment. That is a fixable thing.', true, 'exams', 196, 'fast-national-university-of-computer-and-emerging-sciences', 'Islamabad'),
  ('4acc305e-a302-5b75-a54a-1f73d5dbe2fc'::uuid, 'e95a66ce-9aa8-5651-af65-6e855a250048'::uuid, 'If you are in the economics department and quietly wondering whether you should have done computer science instead: the answer is that you can do both, badly, for two years, and then decide. Ask me how I know.', true, 'advice', 214, 'national-university-of-sciences-and-technology', 'Islamabad'),
  ('09d9e280-086e-5f85-a958-396fae759205'::uuid, '0e4df7cc-5ef6-50c1-a170-96545dc6d150'::uuid, 'Reminder that the department will not accept late submissions for any reason they consider discretionary. Back up your work. Email yourself the draft. I am saying this from experience and the experience was expensive.', true, 'exams', 240, 'lahore-university-of-management-sciences', 'Lahore')
) as v(id, author_id, body, is_anonymous, category, age_hours, uni_slug, campus_city)
join public.universities u on u.slug = v.uni_slug
join public.campuses c on c.university_id = u.id and c.city = v.campus_city
join public.channels ch on ch.campus_id = c.id
on conflict (id) do nothing;

