insert into public.comments (id, post_id, author_id, body, is_anonymous, created_at)
select v.id, v.post_id, v.author_id, v.body, v.is_anonymous, now() - (v.age_minutes || ' minutes')::interval
from (values
  ('7b77c8ac-b194-5618-abc0-625de3458335'::uuid, 'b9ab15c3-97d3-5f15-a20d-5f33b3a482a5'::uuid, '9a147d3a-43d9-5330-a498-d74bfc593a36'::uuid, 'This is the nicest thing I have read on here.', false, 95),
  ('f4d916ab-34dd-53e5-ab68-c1227440cf8a'::uuid, 'b9ab15c3-97d3-5f15-a20d-5f33b3a482a5'::uuid, '519b8ad4-c52f-5fbd-a43e-db8b44f9593b'::uuid, 'Same thing happened to me in September. There are more decent people here than it feels like.', true, 88),
  ('7403a4b9-d395-5cc5-a0dc-f373ec726f60'::uuid, 'ff74ddb0-ce13-5ec9-afb8-0a00bd3d9831'::uuid, '5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, 'Fourth semester is the first one where the courses stop being independent. It is not harder content, it is more of it, all at once.', false, 200),
  ('576aa8c2-8e5e-5ba0-ac5f-47d9ce39680c'::uuid, 'ff74ddb0-ce13-5ec9-afb8-0a00bd3d9831'::uuid, 'e95a66ce-9aa8-5651-af65-6e855a250048'::uuid, 'Agreed with the above. Pick two societies maximum for that semester. You can go back to three afterwards.', false, 190),
  ('a7860ae8-0933-58ac-a747-2362a16d1696'::uuid, 'ff74ddb0-ce13-5ec9-afb8-0a00bd3d9831'::uuid, 'f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'This is genuinely useful, thank you both.', false, 176),
  ('0d4b4359-80d6-500d-a98b-a9477f9934c5'::uuid, '75adb29c-f9f6-57ab-a29a-2b3a3da21e4a'::uuid, '0afbfff3-f104-5daa-afa9-111a9787dcba'::uuid, 'Eleven days is nothing. Ask the 2023 batch about the rice month.', true, 240),
  ('873bd774-6875-5003-a8cf-e516754e2e42'::uuid, '75adb29c-f9f6-57ab-a29a-2b3a3da21e4a'::uuid, '52c4e77d-a51d-5f55-a2d1-f08feee355e8'::uuid, 'You can raise it through the hostel committee and they do actually respond. Two people is enough to file a complaint.', false, 230),
  ('c0ed8db3-f9e8-5d6b-a680-9591ecef05d4'::uuid, '663d99ee-6ed3-5dc2-a406-3e983435d8b8'::uuid, '969ca84f-b57e-5027-a588-1c9385f61feb'::uuid, 'Second-year me needed this post and I did not have it. Saving it for the next person who needs it.', false, 400),
  ('af89aac6-edd2-5466-ae23-0cfecf9c7980'::uuid, '1d971267-94d6-5fab-a23c-09c838fa1808'::uuid, 'c616a515-1909-5334-ac6e-a9aae9284832'::uuid, 'Adding that the office accepts a signed statement from a guardian if the income documents are in someone else''s name. Saved me a whole trip.', false, 320),
  ('f9c18376-24dd-5fec-af52-6e7acdf89874'::uuid, 'd61e8b23-f68c-51c2-aa9c-ac83961b1cd6'::uuid, '1ad7f11d-5e3c-5dd7-a9c7-7bb5f7964cec'::uuid, 'I did it last year. The department waived it after I showed the course outline and asked politely. Go to the office in person.', false, 300),
  ('42ec95f7-3eee-51e6-a628-b84de6dc29e9'::uuid, 'd61e8b23-f68c-51c2-aa9c-ac83961b1cd6'::uuid, '519b8ad4-c52f-5fbd-a43e-db8b44f9593b'::uuid, 'Also worth asking if you can sit the first quiz and have it count as the prerequisite check. That is how mine was handled.', true, 288)
) as v(id, post_id, author_id, body, is_anonymous, age_minutes)
join public.posts p on p.id = v.post_id
on conflict (id) do nothing;

insert into public.saved_posts (user_id, post_id, created_at)
select v.user_id, v.post_id, now()
from (values
  ('f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, '4fe53211-7905-59b6-a15c-c0805e8180e0'::uuid),
  ('f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, '2325c9d7-58f9-53c7-a17c-0f7229987f2f'::uuid),
  ('5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, '245143b6-01f4-5475-acc9-11a90fd227eb'::uuid)
) as v(user_id, post_id)
join public.posts p on p.id = v.post_id
on conflict (user_id, post_id) do nothing;

-- Drafts: private to their owner until published.
insert into public.drafts (id, user_id, channel_id, body, is_anonymous, updated_at)
select v.id, v.author_id, ch.id, v.body, true, now()
from (values
  ('2ace0d6f-6ea6-52ba-a628-e9af9db477af'::uuid, 'f288b60e-e9f4-52b6-a0ef-ed79566aa531'::uuid, 'Midterms week survival guide — does anyone actually finish the DB assignment on time?', 'fast-nuces-peshawar'),
  ('c80cab32-f335-5c32-a557-b556f051d1ac'::uuid, '5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, 'Draft: honest review of the fourth semester workload. Needs a conclusion.', 'nust-islamabad')
) as v(id, author_id, body, channel_slug)
join public.channels ch on ch.slug = v.channel_slug
on conflict (id) do nothing;

