-- 8. Two open reports so the moderation queue is not empty ----------------
insert into public.reports (id, reporter_id, target_type, target_id, reason, description, target_snapshot, status, created_at)
select v.id, v.reporter_id, v.target_type::public.report_target, v.target_id, v.reason::public.report_reason, v.description, v.snapshot::jsonb, 'open', now() - (v.age_hours || ' hours')::interval
from (values
  ('fcc7a35c-662d-52db-a107-83b4b0a2c727'::uuid, '5ae52907-c5fd-5c4d-a667-aca45ecce074'::uuid, 'post', '730f3ea5-e0f5-5991-ac96-7fc95d8e90cf'::uuid, 'harassment', 'Names a specific hostel room and a person. Please review.', '{"body":"[snapshot withheld from this seed file]"}', 6),
  ('86c413e7-9ce3-5e19-adc9-504475f3179b'::uuid, '9851c869-e57e-5937-a1f8-8246907504f2'::uuid, 'comment', '873bd774-6875-5003-a8cf-e516754e2e42'::uuid, 'spam', 'Repeated advertising for a paid service.', '{"body":"[snapshot withheld from this seed file]"}', 2)
) as v(id, reporter_id, target_type, target_id, reason, description, snapshot, age_hours)
where exists (select 1 from public.posts p where p.id = v.target_id)
   or exists (select 1 from public.comments cm where cm.id = v.target_id)
on conflict (id) do nothing;

commit;

